//! Wolfram golden replay: Lagrange reference-element tabulation.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `fixtures/basis_golden.wls` under Wolfram Engine 15.0.0) evaluates the
//! P1/P2 tetrahedron and Q1 hexahedron shape functions and gradients at an
//! interior point with the crate's exact node ordering. Basis transcription
//! or node-ordering slips corrupt every assembly downstream, so the replay
//! checks every value and every gradient component through the public
//! [`evaluate_shape`](sonium_fem::basis::evaluate_shape) entry point.

use serde::Deserialize;
use sonium_fem::basis::{PolynomialDegree, evaluate_shape};
use sonium_fem::mesh::ElementType;
use std::collections::HashMap;

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Entry {
    values: Vec<String>,
    exact: String,
}

#[derive(Debug, Deserialize)]
struct Meta {
    engine: String,
    protocol: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    meta: Meta,
    values: HashMap<String, Entry>,
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram basis fixture");
    assert!(
        fixture.meta.engine.contains("Wolfram Engine"),
        "fixture must record its Wolfram provenance"
    );
    assert_eq!(fixture.meta.protocol, "audit-oracle-hermetic-v1");
    fixture
}

fn vector(fixture: &Fixture, name: &str) -> Vec<f64> {
    fixture.values[name]
        .values
        .iter()
        .map(|s| s.parse().expect("golden holds decimals"))
        .collect()
}

fn check_case(
    fixture: &Fixture,
    element: ElementType,
    degree: PolynomialDegree,
    point: (f64, f64, f64),
    values_name: &str,
    grads_name: &str,
) {
    let shape = evaluate_shape(element, degree, point.0, point.1, point.2);
    let expected_values = vector(fixture, values_name);
    assert_eq!(
        shape.values.len(),
        expected_values.len(),
        "{values_name} arity"
    );
    for (index, (&actual, &expected)) in shape.values.iter().zip(&expected_values).enumerate() {
        assert!(
            (actual - expected).abs() < 1e-14,
            "{values_name}[{index}]: Rust {actual} vs Wolfram {expected}"
        );
    }
    let expected_grads = vector(fixture, grads_name);
    assert_eq!(
        shape.gradients.len(),
        expected_grads.len(),
        "{grads_name} arity"
    );
    assert_eq!(shape.grad_dim, 3, "gradient dimension");
    for (index, (&actual, &expected)) in shape.gradients.iter().zip(&expected_grads).enumerate() {
        assert!(
            (actual - expected).abs() < 1e-14,
            "{grads_name}[{index}]: Rust {actual} vs Wolfram {expected}"
        );
    }
}

#[test]
fn p1_tetrahedron_tabulation_matches_wolfram() {
    let fixture = parse_fixture();
    check_case(
        &fixture,
        ElementType::Tetrahedron,
        PolynomialDegree::P1,
        (0.2, 0.3, 0.1),
        "p1_tet_vals",
        "p1_tet_grads",
    );
}

#[test]
fn p2_tetrahedron_tabulation_matches_wolfram() {
    let fixture = parse_fixture();
    assert!(
        fixture.values["p2_tet_vals"]
            .exact
            .contains("canonical edges"),
        "P2 golden must document the edge ordering"
    );
    check_case(
        &fixture,
        ElementType::Tetrahedron,
        PolynomialDegree::P2,
        (0.2, 0.3, 0.1),
        "p2_tet_vals",
        "p2_tet_grads",
    );
}

#[test]
fn q1_hexahedron_tabulation_matches_wolfram() {
    let fixture = parse_fixture();
    check_case(
        &fixture,
        ElementType::Hexahedron,
        PolynomialDegree::P1,
        (0.1, 0.2, 0.3),
        "q1_hex_vals",
        "q1_hex_grads",
    );
}
